__NUXT_JSONP__("/think-tanks/noticias/los_think_tanks_aprendieron_a_sobrevivir_y_evolucionar_pese_al_ambiente_adverso_con_la_4t", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q,r,s,t,u,v,w,x,y){return {data:[{post:{slug:"los_think_tanks_aprendieron_a_sobrevivir_y_evolucionar_pese_al_ambiente_adverso_con_la_4t",title:"Los Think Tanks aprendieron a sobrevivir y evolucionar pese al ambiente adverso con la 4T",date:"2024-05-13T17:26:20.993Z",img:"https:\u002F\u002Fucarecdn.com\u002F969f1cec-f61b-4430-9ce8-3454119a4b58\u002F","img-alt":"Liliana Alvarado ",autor:"Diego Badillo, El Economista",link:"https:\u002F\u002Fwww.eleconomista.com.mx\u002Fpolitica\u002FLos-Think-Tanks-aprendieron-a-sobrevivir-y-evolucionar-pese-al-ambiente-adverso-con-la-4T-20240512-0008.html",category:"think-tanks",extracto:"Los centros de pensamiento especializados en investigación y análisis de políticas públicas han trabajado en un ambiente adverso con el gobierno actual, lo cual los ha obligado a evolucionar en el rol que desempeñan y con quién se relacionan, exponen directoras de esas organizaciones",toc:[{id:r,depth:k,text:s},{id:t,depth:k,text:u},{id:v,depth:k,text:w}],body:{type:"root",children:[{type:b,tag:d,props:{},children:[{type:a,value:"Durante la administración del presidente, "},{type:b,tag:e,props:{},children:[{type:a,value:"Andrés Manuel López Obrador"}]},{type:a,value:", los"},{type:b,tag:f,props:{href:"https:\u002F\u002Fwww.eleconomista.com.mx\u002Fopinion\u002FEl-contrapeso-gubernamental-a-la-baja-20220222-0057.html",rel:[g,h,i],target:j},children:[{type:a,value:x},{type:b,tag:e,props:{},children:[{type:a,value:"centros de pensamiento especializados en investigación"}]},{type:a,value:x}]},{type:a,value:"y análisis de políticas públicas, han trabajado en un ambiente adverso con el gobierno, lo cual los ha obligado a evolucionar en el rol que desempeñan y con quién se relacionan."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:b,tag:e,props:{},children:[{type:a,value:"Liliana Alvarado"}]},{type:a,value:", directora general de Ethos Innovación en de Políticas Públicas, describe que esas organizaciones no tienen una relación estrecha con la administración pública federal. “ "},{type:b,tag:e,props:{},children:[{type:a,value:"Los canales de comunicación están debilitados o rotos”."}]}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Dice que no hay disposición a escucharlas y menos si su objeto de estudio son corrupción, transparencia y rendición de cuentas."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"La analista, especialista en políticas públicas, recuerda que siempre ha habido ―y va a haber ― resistencias de los gobiernos a tratar ese tipo de asuntos y a que alguien lo señale; sin embargo, destaca que, en otras administraciones, eso "},{type:b,tag:e,props:{},children:[{type:a,value:"no había sido un obstáculo para sentarse a dialogar,"}]},{type:a,value:" como sucede ahora."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Liliana Alvarado menciona que el problema es que, al "},{type:b,tag:e,props:{},children:[{type:a,value:"cerrarse la posibilidad de diálogo"}]},{type:a,value:" entre el gobierno y esas organizaciones, no solo pierden ellas, sino que perdemos todos como sociedad, ya que se puede estar perdiendo, al menos en algunos casos, la oportunidad de solucionar problemas públicos con base en conocimiento."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Destaca que, muchas veces el gobierno no tiene ni el tiempo ni los recursos ni las capacidades para invertirle a ciertos temas, de la manera en que los "},{type:b,tag:e,props:{},children:[{type:a,value:"think tanks"}]},{type:a,value:" lo hacen."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Liliana Alvarado llama la atención que, en muchos casos, los "},{type:b,tag:e,props:{},children:[{type:a,value:"think tanks,"}]},{type:a,value:" lejos de tener una relación cordial con el gobierno, "},{type:b,tag:e,props:{},children:[{type:a,value:"se han vuelto contrapesos"}]},{type:a,value:". Eso explica, en muchas ocasiones, que no haya una buena relación entre ambos."}]},{type:a,value:c},{type:b,tag:l,props:{id:r},children:[{type:b,tag:f,props:{href:"#repensaron-su-rol",ariaHidden:m,tabIndex:n},children:[{type:b,tag:o,props:{className:[p,q]},children:[]}]},{type:a,value:s}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Ante esa situación, muchos de esos centros de pensamiento han tenido que repensar su rol y sus actividades."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"En ese sentido Alvarado señala que, si en un principio los también llamados "},{type:b,tag:e,props:{},children:[{type:a,value:"think tanks estaban orientados a generar análisis"}]},{type:a,value:" para el sector público y ahora tienen la puerta cerrada con él, tienen, que buscar en otras partes."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Refiere que no todo es un asunto perdido porque, si bien se les han cerrado las puertas con el gobierno, en el caso particular de Ethos, se les han abierto otras, particularmente con gobiernos estatales y municipales."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"“Al final, las organizaciones "},{type:b,tag:e,props:{},children:[{type:a,value:"hemos sabido ser resilientes"}]},{type:a,value:" y hemos sabido adaptarnos”."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Incluso ha cambiado lo que consideran éxito. Por ejemplo, antes se les consideraba éxito c"},{type:b,tag:f,props:{href:"https:\u002F\u002Fwww.eleconomista.com.mx\u002Fopinion\u002FLos-retos-de-los-Think-Tanks-en-la-era-de-la-nueva-normalidad-20210707-0026.html",rel:[g,h,i],target:j},children:[{type:a,value:"uando lograban hacer cambios en una política pública"}]},{type:a,value:", pues se conseguía impacto e incidencia. Ahora, se han dado cuenta que para lograr eso no necesariamente es vía el gobierno federal."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Por su parte "},{type:b,tag:e,props:{},children:[{type:a,value:"Sofía Ramírez Aguilar, directora general de México, ¿cómo vamos?"}]},{type:a,value:", considera que, como país, cada vez más se está aprovechando el trabajo de estos centros."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"“En el sector empresarial organizado cada vez más nos retoman, los grupos legislativos de todos los colores nos retoman y los "},{type:b,tag:e,props:{},children:[{type:a,value:"gobiernos locales nos tienen en gran estima"}]},{type:a,value:"”."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Cuenta que su anécdota más feliz es cuando, en una junta de condóminos se utilizó una gráfica realizada en ese centro sobre el incremento en los energéticos, en particular en gasolina y gas, a partir del índice nacional de precios al consumidor, lo cual muestra que su trabajo sirve para la discusión comunitaria y no solo se queda en el llamado círculo rojo."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Señala que, en el caso de México, ¿cómo vamos?, han logrado incrementar su alcance en distintos públicos, para lo cual han tenido que invertir, tiempo dinero y presupuesto para comunicar mejor, pues el reto al que se han enfrentado es, no solo generar investigaciones serias, sino comunicarlas con distintos públicos y a través de diferentes vías."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Para lograrlo, han realizado alianzas con otras organizaciones, universidades y medios de comunicación, con el fin de llegar a más públicos y ser parte de las agendas que les interesan."}]},{type:a,value:c},{type:b,tag:l,props:{id:t},children:[{type:b,tag:f,props:{href:"#conseguir-financiamiento-los-estresa",ariaHidden:m,tabIndex:n},children:[{type:b,tag:o,props:{className:[p,q]},children:[]}]},{type:a,value:u}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Por otra parte, Liliana Alvarado considera que el cambio de rol de esos centros de pensamiento se explica también por el "},{type:b,tag:e,props:{},children:[{type:a,value:"papel que tienen las financiadoras."}]}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"En un principio, recibían financiamiento para que produjeran insumos que pudieran generar cambios en políticas públicas, los cuales se materializaban en modificaciones a leyes y reglamentos."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Lo que ha ocurrido en los últimos años, es que algunas financiadoras (que, por cierto, no son estáticas en sus políticas y siempre quieren el mejor retorno por su inversión), prefieren ya apoyar proyectos mucho más tangibles."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"El "},{type:b,tag:e,props:{},children:[{type:b,tag:f,props:{href:"https:\u002F\u002Fwww.eleconomista.com.mx\u002Fopinion\u002FEntre-las-mejores-calificadas-20200203-0063.html",rel:[g,h,i],target:j},children:[{type:a,value:"mensaje hacia los think tanks"}]}]},{type:a,value:" es: ya no quiero un estudio o una investigación, sino algo mucho más aplicable con resultados mucho más tangibles. Por ello buscan organizaciones que trabajen directamente con las personas."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Menciona que el tema de financiamiento es la preocupación de todos los días, porque no tienen garantizado nada. "},{type:b,tag:e,props:{},children:[{type:a,value:"“Es un tema muy estresante”."}]}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Antes había recursos del sector público, ahora prácticamente no hay; antes podían hacer consultoría para el gobierno, ahora casi no ocurre, además de que eso no es sostenible. Eso les suma estrés."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"El financiamiento que les permite mantener su independencia es el que viene de los "},{type:b,tag:e,props:{},children:[{type:a,value:"financiadores internacionales"}]},{type:a,value:" y de las agencias de desarrollo internacional."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"El problema es que, desde la pandemia de la Covid-19, han tenido más dificultades de acceder a ellos porque muchas financiadoras repensaron sus prioridades y en algunos casos, buscan apoyar temas que no forman parte de sus agendas."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"También llamó la atención en que ahora los financiamientos ya no son multianuales y son más pequeños, lo cual complica la operación y mantener a los equipos."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Al respecto, Sofía Ramírez Aguilar, directora general de México, ¿cómo vamos?, refiere que el problema es que, como centro de pensamiento, muchas veces no son elegibles para recibir apoyos de donantes internacionales, sobre todo porque sus temas de investigación no están dentro de la agenda de esos donantes."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Puso como ejemplo que muchos están "},{type:b,tag:e,props:{},children:[{type:a,value:"interesados en financiar investigación en Estado de derecho,"}]},{type:a,value:" corrupción, justicia y seguridad, pero, fuera de esos temas, es muy difícil acceder a su apoyo."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"También llamó la atención que hoy es más complicado ser considerada organización donataria si eres un centro de pensamiento, porque tienen que estar vinculada al fondo del Consejo Nacional de Humanidades Ciencias y Tecnologías (Conahcyt) y no tiene recursos y es muy probable que así permanezca, al menos en el corto plazo."}]},{type:a,value:c},{type:b,tag:l,props:{id:v},children:[{type:b,tag:f,props:{href:"#cu%C3%A1les-son-las-preguntas-que-se-hacen",ariaHidden:m,tabIndex:n},children:[{type:b,tag:o,props:{className:[p,q]},children:[]}]},{type:a,value:w}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Liliana Alvarado considera que en el mundo de los think tanks, una de las preguntas relevantes de hoy es cuál es su relación con la sociedad y como conviven con su comunidad."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Antes no la tenían, pues buscaban relacionarse con los que toman las decisiones para solucionar los problemas públicos."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"“Si nosotros trabajamos con otras organizaciones de la sociedad civil, tal vez a escala estatal y con jóvenes o grupos indígenas o si difundimos nuestro conocimiento con la población en general, también "},{type:b,tag:e,props:{},children:[{type:a,value:"podemos generar presión,"}]},{type:a,value:" de abajo para arriba para generar los cambios esperados, reflexiona."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Eso explica que ahora estén haciendo esfuerzos por comunicar de manera sencilla de forma tal que también puedan incidir en la sociedad."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Para México ¿cómo vamos? Las"},{type:b,tag:f,props:{href:"https:\u002F\u002Fwww.eleconomista.com.mx\u002Fsectorfinanciero\u002FCasi-8-de-las-remesas-recibidas-en-2022-estan-relacionadas-con-lavado-de-dinero-y-narcotrafico-informe-20230328-0037.html",rel:[g,h,i],target:j},children:[{type:a,value:" áreas de oportunidad están en seguir explorando mecanismos de comunicación h"}]},{type:a,value:"acia los distintos públicos y generar información tan precisa como lo requieran cada uno de ellos."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"En su opinión se espera que haya una interacción importante con la sociedad organizada del país y ser fuente de información, ya no solo para legisladores y gobiernos, sino ser una fuente para alimentar las propias causas de las comunidades."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Destaca que hay una "},{type:b,tag:e,props:{},children:[{type:a,value:"ciudadanía interesada en la vida pública"}]},{type:a,value:", con la ventaja de que ahora puede acceder a información pública procesada que se contrasta con las vivencias cotidianas de la gente."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"“Lo que podemos esperar es una mayor apertura a colaborar con cualquier actor social, económico o político”."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Es una "},{type:b,tag:e,props:{},children:[{type:a,value:"forma de enriquecer la discusión pública"}]},{type:a,value:" de manera apartidista."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Ser "},{type:b,tag:e,props:{},children:[{type:a,value:"científica o ingeniera"}]},{type:a,value:" no garantiza solucionar problemas públicos con base en conocimiento"}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Por otra parte, para Liliana Alvarado, el hecho de que las candidatas a la presidencia de la república estén más acostumbradas al uso de los datos y que una es científica y otra ingeniera, no asegura una mejor relación entre el gobierno que encabecen, con los think tanks."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"“Eso no es una garantía absolutamente de nada. Si bien pueden vender esa idea de creemos en la ciencia y en la tecnología, no quiere decir que haya realmente una voluntad por tener una interrelación con el "},{type:b,tag:e,props:{},children:[{type:a,value:"sector de los think tanks"}]},{type:a,value:", aunque, remarca, los centros de pensamiento siempre estarán en la mejor de las disposiciones para sumar."}]}]},dir:"\u002Fnoticias",path:"\u002Fnoticias\u002Flos_think_tanks_aprendieron_a_sobrevivir_y_evolucionar_pese_al_ambiente_adverso_con_la_4t",extension:".md",createdAt:y,updatedAt:y}}],fetch:{},mutations:[]}}("text","element","\n","p","strong","a","nofollow","noopener","noreferrer","_blank",2,"h2","true",-1,"span","icon","icon-link","repensaron-su-rol","Repensaron su rol","conseguir-financiamiento-los-estresa","Conseguir financiamiento los estresa","cuáles-son-las-preguntas-que-se-hacen","¿Cuáles son las preguntas que se hacen?"," ","2024-10-02T22:32:44.091Z")));